#ifndef AIEHLC_PROFILING
#define AIEHLC_PROFILING 0
#endif

#if AIEHLC_PROFILING && defined(__aarch64__) && !defined(__AIESIM__)
static inline unsigned long long __rt_pmccntr(void) {
    unsigned long long v;
    __asm__ volatile("mrs %0, pmccntr_el0" : "=r"(v));
    return v;
}
#else
static inline unsigned long long __rt_pmccntr(void) { return 0ULL; }
#endif

// Start the cycle counter the RT_PROF_* phases read. Nothing else does: the
// standalone BSP boot.S never touches PMCR_EL0, whose E bit resets to 0, so
// without this pmccntr_el0 stays frozen and every phase delta is 0 -- a
// --profiling build that reports "not built in". Apps used to call aie_timer.h's
// __ps_pmccntr_enable() themselves; one that did not (conv2dstem test_conv2d.cc)
// silently got zeros. Same bits as that helper (E=1, D=0 so it counts every
// cycle, PMCNTENSET.C) minus the C reset: only deltas are used, and resetting
// would invalidate a snapshot the app already took. Baremetal only -- under
// Linux PMCR_EL0 is EL1-owned and an EL0 write traps.
static inline void __rt_pmccntr_enable(void) {
#if AIEHLC_PROFILING && defined(__aarch64__) && !defined(__AIESIM__) && !defined(__linux__)
    unsigned long long v;
    __asm__ volatile("mrs %0, pmcr_el0" : "=r"(v));
    v |= (1ULL << 0);
    v &= ~(1ULL << 3);
    __asm__ volatile("msr pmcr_el0, %0" : : "r"(v));
    __asm__ volatile("msr pmcntenset_el0, %0" : : "r"(1ULL << 31));
    __asm__ volatile("isb");
#endif
}

static unsigned long long g_prof_excl_cyc = 0ULL;
static inline unsigned long long __rt_prof_now(void) { return __rt_pmccntr() - g_prof_excl_cyc; }

#if AIEHLC_PROFILING
#define RT_PROF_TIC() __rt_prof_now()
#define RT_PROF_ADD(cyc, n, t0)                                                                                        \
    do {                                                                                                               \
        (cyc) += (__rt_prof_now() - (t0));                                                                             \
        (n)++;                                                                                                         \
    } while (0)
#define RT_PROF_PHASE(ph, t0) __rt_ph_add((ph), (t0))
#define RT_PROF_INC(v)                                                                                                 \
    do {                                                                                                               \
        (v)++;                                                                                                         \
    } while (0)
#else
#define RT_PROF_TIC() 0ULL
#define RT_PROF_ADD(cyc, n, t0)                                                                                        \
    do {                                                                                                               \
        (void)(t0);                                                                                                    \
    } while (0)
#define RT_PROF_PHASE(ph, t0)                                                                                          \
    do {                                                                                                               \
        (void)(t0);                                                                                                    \
    } while (0)
#define RT_PROF_INC(v)                                                                                                 \
    do {                                                                                                               \
    } while (0)
#endif

static unsigned long long g_wait_io_cycles = 0ULL;
static unsigned int g_wait_io_calls = 0U;
static unsigned long long g_wait_io_iters = 0ULL;
static int g_ctrl_high_throughput = 0;
static int g_ctrl_high_throughput_ready = 0;

enum { PH_KLOAD = 0, PH_BDCFG = 1, PH_COREEN = 2, PH_STARTIO = 3, PH_N = 4 };
static unsigned long long g_ph_cyc[PH_N] = {0, 0, 0, 0};
static unsigned int g_ph_calls[PH_N] = {0, 0, 0, 0};

static unsigned long long g_bd_init_cyc = 0ULL, g_bd_write_cyc = 0ULL;
static unsigned int g_bd_init_n = 0U, g_bd_write_n = 0U;
static unsigned long long g_bd_mid_cyc = 0ULL, g_bd_tail_cyc = 0ULL;
static unsigned int g_bd_mid_n = 0U, g_bd_tail_n = 0U;
static unsigned long long g_bd_gtt_cyc = 0ULL, g_bd_saddr_cyc = 0ULL, g_bd_en_cyc = 0ULL;
static unsigned int g_bd_gtt_n = 0U, g_bd_saddr_n = 0U, g_bd_en_n = 0U;
static unsigned long long g_kl_elf_cyc = 0ULL, g_kl_rst_cyc = 0ULL;
static unsigned int g_kl_elf_n = 0U, g_kl_rst_n = 0U;
static unsigned long long g_kl_elf_fill_cyc = 0ULL;
static unsigned int g_kl_elf_fill_n = 0U;
static int g_kl_ctrlpkt_aot = 0;
static unsigned long long g_ctrl_plan_cyc = 0ULL, g_sync_dev_cyc = 0ULL;
/* Bumped by every partition init and teardown. Anything cached against the
 * array's register state (rt_plan_cache below) is valid only within one
 * generation: a re-init resets the stream switches it describes. */
static unsigned g_partition_gen = 1U;
static unsigned int g_ctrl_plan_n = 0U, g_sync_dev_n = 0U;
static unsigned long long g_pmap_print_cyc = 0ULL;
static unsigned int g_pmap_print_n = 0U;

#if AIEHLC_PROFILING
static inline void __rt_ph_add(int ph, unsigned long long t0) {
    g_ph_cyc[ph] += (__rt_prof_now() - t0);
    g_ph_calls[ph]++;
}
#endif

void __Runtime_wait_io_cycles(unsigned long long *cycles, unsigned int *calls) {
    if (cycles)
        *cycles = g_wait_io_cycles;
    if (calls)
        *calls = g_wait_io_calls;
}
void __Runtime_wait_io_iters(unsigned long long *iters) {
    if (iters)
        *iters = g_wait_io_iters;
}

void __Runtime_ctrl_high_throughput_enable(int on) {
    g_ctrl_high_throughput = on ? 1 : 0;
    if (!on)
        g_ctrl_high_throughput_ready = 0;
}
void __Runtime_phase_cycles(unsigned long long *cyc, unsigned int *calls) {
    for (int i = 0; i < PH_N; i++) {
        if (cyc)
            cyc[i] = g_ph_cyc[i];
        if (calls)
            calls[i] = g_ph_calls[i];
    }
}
